use std::fs

fn main() {
    let max: int = 200000
    let mut sieve: Vec<bool> = []
    let mut q: int = 0
    while q <= max {
        sieve.push(true)
        q += 1
    }
    let mut cnt: Vec<int> = []
    let mut last: Vec<int> = []
    let mut c: int = 0
    let mut l: int = -1
    let mut i: int = 0
    while i <= max {
        if i >= 2 && sieve[i] {
            c += 1
            l = i
            let mut j: int = i * i
            while j <= max {
                sieve[j] = false
                j += i
            }
        }
        cnt.push(c)
        last.push(l)
        i += 1
    }
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut first = true
    for line in text.lines() {
        if first {
            first = false
            continue
        }
        let s = line.trim()
        if s == "" { continue }
        let n: int = s.parse().unwrap_or(0)
        if last[n] < 0 {
            println("0 none")
        } else {
            println("${cnt[n]} ${last[n]}")
        }
    }
}

